def transform(grid):
    h,w=len(grid),len(grid[0])
    start=next(((r,c) for r in range(h) for c in range(w) if grid[r][c]!=0),None)
    if start is None: return [row[:] for row in grid]
    seen={start}; todo=[start]
    while todo:
        r,c=todo.pop()
        for a,b in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=a<h and 0<=b<w and grid[a][b]!=0 and (a,b) not in seen:
                seen.add((a,b)); todo.append((a,b))
    r0=min(r for r,c in seen); r1=max(r for r,c in seen)
    c0=min(c for r,c in seen); c1=max(c for r,c in seen)
    return [row[c0:c1+1] for row in grid[r0:r1+1]]

